using System.Collections.Generic;
using System.Linq;
using MultiFPS;
using MultiFPS.Gameplay;
using MultiFPS.Gameplay.RiftCombat;
using MultiFPS.Gameplay.RiftEnemies;
using MultiFPS.UI;
using UnityEngine;
using UnityEngine.UI;
namespace ROM.UI.Gameplay {
// Presentation only: reads the existing replicated Health state of Rift enemies.
[DefaultExecutionOrder(1250)]public sealed class RiftEnemyNameplates:MonoBehaviour {
 public const int MaximumVisible=8;public float MaximumDistance=32;
 sealed class Row{public RectTransform Root;public Text Name;public RiftHUDGraphic Back,Fill;public Health Health;public Renderer[] Visuals;}
 readonly List<Row> rows=new List<Row>();readonly RaycastHit[] hits=new RaycastHit[48];readonly Dictionary<Health,Renderer[]> visuals=new Dictionary<Health,Renderer[]>();
 RiftGameplayHUD hud;RiftFieldUI field;float next;Camera view;CharacterInstance actor;
 public int VisibleCount=>rows.Count(r=>r.Root.gameObject.activeSelf);
 public bool IsShown(Health health)=>rows.Any(r=>r.Root.gameObject.activeSelf&&r.Health==health);
 public float FillFor(Health health){var row=rows.FirstOrDefault(r=>r.Root.gameObject.activeSelf&&r.Health==health);return row!=null?row.Fill.Fill:-1;}
 void Awake(){hud=GetComponent<RiftGameplayHUD>();for(int i=0;i<MaximumVisible;i++){var root=RiftHUDIntegratedBar.Rect(hud.Design,"Enemy nameplate "+i,0,0,160,28);root.anchorMin=root.anchorMax=Vector2.zero;root.pivot=new Vector2(.5f,0);var group=root.gameObject.AddComponent<CanvasGroup>();group.blocksRaycasts=group.interactable=false;var name=RiftHUDIntegratedBar.Rect(root,"Replicated enemy name",0,0,160,17).gameObject.AddComponent<Text>();name.font=hud.Theme.BodyFont;name.fontSize=12;name.alignment=TextAnchor.MiddleCenter;name.raycastTarget=false;var shadow=name.gameObject.AddComponent<Outline>();shadow.effectColor=new Color(0,0,0,.9f);shadow.effectDistance=new Vector2(.8f,-.8f);var back=RiftHUDIntegratedBar.Rect(root,"Health background",10,20,140,7).gameObject.AddComponent<RiftHUDGraphic>();back.Shape=HUDShape.Bar;back.color=new Color(.035f,.023f,.03f,.98f);back.Bottom=back.color;back.Border=new Color(.26f,.12f,.14f);back.Thickness=1;back.raycastTarget=false;var fill=RiftHUDIntegratedBar.Rect(root,"Replicated health fill",11,21,138,5).gameObject.AddComponent<RiftHUDGraphic>();fill.Shape=HUDShape.Bar;fill.color=new Color(.73f,.035f,.055f);fill.Bottom=new Color(.34f,.015f,.025f);fill.Thickness=0;fill.raycastTarget=false;root.gameObject.SetActive(false);rows.Add(new Row{Root=root,Name=name,Back=back,Fill=fill});}}
 static bool Enemy(Health h)=>h&&!h.TrainingTarget&&(h.GetComponent<RiftEnemyAgent>()||h.GetComponent<RiftEnemyCombat>());
 Renderer[] Visuals(Health health){if(visuals.TryGetValue(health,out var cached))return cached;var c=health.GetComponent<CharacterInstance>();var root=c&&c.CharacterParent?c.CharacterParent:health.transform;cached=root.GetComponentsInChildren<Renderer>().Where(r=>(r is SkinnedMeshRenderer||r is MeshRenderer)&&!r.GetComponent<TextMesh>()).ToArray();visuals[health]=cached;return cached;}
 Vector3 Head(Health health,Renderer[] renderers){bool found=false;Bounds bounds=default;foreach(var r in renderers)if(r&&r.enabled&&r.gameObject.activeInHierarchy){if(!found){bounds=r.bounds;found=true;}else bounds.Encapsulate(r.bounds);}return found?new Vector3(bounds.center.x,bounds.max.y+.12f,bounds.center.z):health.transform.position+health.centerPosition+Vector3.up*.3f;}
 bool Visible(Health health,Vector3 point){var screen=view.WorldToViewportPoint(point);if(screen.z<=0||screen.x<.015f||screen.x>.985f||screen.y<.04f||screen.y>.96f)return false;var ray=new Ray(view.transform.position,point-view.transform.position);float distance=Vector3.Distance(ray.origin,point);int count=Physics.RaycastNonAlloc(ray,hits,distance,~0,QueryTriggerInteraction.Ignore);if(count==hits.Length)return false;for(int i=0;i<count;i++){var collider=hits[i].collider;if(!collider||!collider.enabled)continue;var hitbox=collider.GetComponent<HitBox>();var owner=hitbox?hitbox._health:collider.GetComponentInParent<Health>();if(owner==health||owner==actor.Health)continue;if(hits[i].distance<distance-.06f)return false;}return true;}
 void Hide(){foreach(var row in rows)row.Root.gameObject.SetActive(false);}
 void LateUpdate(){actor=ClientFrontend.OwnedCharacterInstance;view=GameplayCamera._instance?GameplayCamera._instance.GetComponent<Camera>():null;if(!field)field=FindFirstObjectByType<RiftFieldUI>();if(!actor||!view||!hud.GetComponent<Canvas>().enabled||ClientFrontend.Pause||(field&&field.MapOpen)){Hide();return;}if(Time.unscaledTime>=next){next=Time.unscaledTime+.12f;Rebuild();}foreach(var row in rows){if(!row.Root.gameObject.activeSelf)continue;var health=row.Health;if(!health||health.CurrentHealth<=0){row.Root.gameObject.SetActive(false);continue;}var point=view.WorldToScreenPoint(Head(health,row.Visuals));point.y+=9;RectTransformUtility.ScreenPointToLocalPointInRectangle(hud.Design,point,null,out var local);row.Root.anchoredPosition=local-hud.Design.rect.min;float value=Mathf.Clamp01((float)health.CurrentHealth/Mathf.Max(1,health.MaxHealth));if(!Mathf.Approximately(row.Fill.Fill,value)){row.Fill.Fill=value;row.Fill.SetVerticesDirty();}bool selected=hud.SelectedTarget==health;row.Name.text=health.CharacterName;row.Name.fontSize=selected?13:12;row.Name.color=selected?new Color(1,.9f,.77f):new Color(.9f,.84f,.82f);var border=selected?new Color(.95f,.48f,.34f):new Color(.26f,.12f,.14f);if(row.Back.Border!=border){row.Back.Border=border;row.Back.SetVerticesDirty();}}}
 bool OverHUD(Rect candidate){var units=hud.GetComponent<RiftUnitFrames>();var bar=hud.GetComponent<RiftHUDIntegratedBar>();var roots=new[]{units?units.PlayerFrame:null,hud.TargetPanel,bar?bar.Root:null,hud.Minimap?hud.Minimap.transform as RectTransform:null};var corners=new Vector3[4];foreach(var rect in roots){if(!rect||!rect.gameObject.activeInHierarchy)continue;rect.GetWorldCorners(corners);RectTransformUtility.ScreenPointToLocalPointInRectangle(hud.Design,RectTransformUtility.WorldToScreenPoint(null,corners[0]),null,out var min);RectTransformUtility.ScreenPointToLocalPointInRectangle(hud.Design,RectTransformUtility.WorldToScreenPoint(null,corners[2]),null,out var max);if(candidate.Overlaps(Rect.MinMaxRect(min.x,min.y,max.x,max.y)))return true;}return false;}
 void Rebuild(){var selected=hud.SelectedTarget;var candidates=Health.All.Where(h=>Enemy(h)&&h!=actor.Health&&h.CurrentHealth>0&&h.gameObject.activeInHierarchy&&h.Team!=actor.Health.Team&&(h.transform.position-actor.transform.position).sqrMagnitude<=MaximumDistance*MaximumDistance).OrderBy(h=>h==selected?0:1).ThenBy(h=>(h.transform.position-actor.transform.position).sqrMagnitude).ToArray();Hide();var placed=new List<Rect>();int index=0;foreach(var health in candidates){var geometry=Visuals(health);var point=Head(health,geometry);if(!Visible(health,point))continue;var screen=view.WorldToScreenPoint(point);screen.y+=9;RectTransformUtility.ScreenPointToLocalPointInRectangle(hud.Design,screen,null,out var local);var rect=new Rect(local.x-80,local.y,160,28);if(OverHUD(rect)||placed.Any(p=>p.Overlaps(rect)))continue;var row=rows[index++];row.Health=health;row.Visuals=geometry;row.Root.gameObject.SetActive(true);placed.Add(rect);if(index==MaximumVisible)break;}foreach(var stale in visuals.Keys.Where(h=>!h||!h.gameObject.activeInHierarchy).ToArray())visuals.Remove(stale);}
 void OnDisable()=>Hide();
}
}
